import type { Page } from "@playwright/test";
/** Synthetic flat-color pixels generated by the test's own canvas, never a sourced photo. */
export async function recipePhoto(
  page: Page,
  type = "image/png",
  width = 2100,
  height = 1400,
  color = "#d97706",
) {
  const data = await page.evaluate(
    ({ type, width, height, color }) => {
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d")!;
      context.fillStyle = color;
      context.fillRect(0, 0, width, height);
      return canvas.toDataURL(type).split(",")[1];
    },
    { type, width, height, color },
  );
  return {
    name:
      "synthetic-photo." +
      (type === "image/png" ? "png" : type === "image/jpeg" ? "jpg" : "webp"),
    mimeType: type,
    buffer: Buffer.from(data, "base64"),
  };
}
export async function displayedPhotoDimensions(page: Page) {
  return page
    .getByTestId("recipe-image")
    .getByRole("img")
    .evaluate(async (img: HTMLImageElement) => {
      await img.decode();
      return {
        width: img.naturalWidth,
        height: img.naturalHeight,
        source: img.src,
      };
    });
}
